vec2 cadd( vec2 a, float s ) { return vec2( a.x+s, a.y ); }
vec2 cmul( vec2 a, vec2 b )  { return vec2( a.x*b.x - a.y*b.y, a.x*b.y + a.y*b.x ); }
vec2 cdiv( vec2 a, vec2 b )  { float d = dot(b,b); return vec2( dot(a,b), a.y*b.x - a.x*b.y ) / d; }
vec2 cpow( vec2 z, float n ) { float r = length( z ); float a = atan( z.y, z.x ); return pow( r, n )*vec2( cos(a*n), sin(a*n) ); }
vec2 csqrt( vec2 z )         { float m = length(z); return sqrt( 0.5*vec2(m+z.x, m-z.x) ) * vec2( 1.0, sign(z.y) ); }
vec2 cconj( vec2 z )         { return vec2(z.x,-z.y); }
vec2 absim( vec2 z )         { return vec2(z.x, abs(z.y)); }
int getdigit( float x, int digit ) {
    if (x >= 0.) {
        return int(mod(x, float(pow(10.,float(digit)))) / pow(10.,float(digit-1))); 
    } else {
        return 9 - int(mod(x, float(pow(10.,float(digit)))) / pow(10.,float(digit-1))); 
    }
}

// Smooth formula from https://iquilezles.org/articles/msetsmooth/
float mixedfractal(vec2 z, vec2 c, float k, float alpha)
{
    float sn = 0.;
    for (float i=0.; i<MAXITER; i++){
        if(dot(z,z) >= threshold) {
            sn = i - log2(log2(dot(z,z))/log2(threshold))/log2(k);
            break;
        }
        z = absim(cpow(z, k))*alpha + cpow(z, k)*(1.-alpha) + c;
    }
    return sn;
}

vec3 colormap(float n){
    return 0.5 + 0.5*cos( 3.0 + n*0.075*2. + vec3(0.0,0.6,1.0));
}

