vec3 render(vec2 uv) 
{
    float alpha = smoothstep(0.1, 0.4, (1.-sin(0.1*iTime))/2.);
    float beta = smoothstep(0.1, 0.4, (1.-sin(0.05*iTime))/2.);
    vec2 c0 = pow(K, 1./(1.-K))*vec2(cos(iTime*0.5),sin(iTime*0.5))-pow(K, K/(1.-K))*vec2(cos(0.5*K*iTime),sin(0.5*K*iTime));
    vec3 color = colormap(mixedfractal(uv*alpha, uv*(1.-alpha) + c0*alpha, K, beta)); 

    float text1 = mandotext(uv, 15.);
    float text2 = burningtext(uv, 15.);
    float text3 = juliatext(uv, 15.);
    float text4 = numbertext(uv, c0, 15.);

    color = mix(color, vec3(text1), text1*(1.-beta));
    color = mix(color, vec3(text2), text2*beta);
    color = mix(color, vec3(text3), text3*alpha);
    color = mix(color, vec3(text4), text4*alpha);

    return color;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fixUV(fragCoord);

    // Time varying pixel color
    float dx = 3./iResolution.y;
    vec3 col;
    for (int i=0; i<AA; i++) {
        for (int j=0; j<AA; j++) {
            vec2 shift = vec2(float(i), float(j))*dx;
            col += render(uv+shift);
        }
    }
    col /= float(AA*AA);

    // Output to screen
    fragColor = vec4(col, 1.0);
}
